const raw = $input.first().json.stdout;
const report = JSON.parse(raw);

return [{
  json: {
    totalTests: report.stats.tests,
    passed: report.stats.passes,
    failed: report.stats.failures,
    passPercent: report.stats.passPercent,
    duration: report.stats.duration,
    startedAt: report.stats.start,
    // On extrait uniquement les tests en échec avec leur message d'erreur,
    // c'est ce qui nourrira le futur prompt d'analyse IA
    failedTests: report.results.flatMap(file =>
      file.suites.flatMap(suite =>
        suite.tests
          .filter(test => test.state === 'failed')
          .map(test => ({
            spec: file.file,
            title: test.title,
            errorMessage: test.err?.message || 'Erreur non spécifiée'
          }))
      )
    )
  }
}];

// On récupère le texte stdout généré par Newman
const output = $input.first().json.stdout;

// On parse la chaîne JSON
const report = JSON.parse(output);

const assertions = report.run.stats.assertions;
const requests = report.run.stats.requests;

return {
  json: {
    status: assertions.failed === 0 ? "PASSED" : "FAILED",
    totalAssertions: assertions.total,
    failedAssertions: assertions.failed,
    passedAssertions: assertions.total - assertions.failed,
    totalRequests: requests.total,
    failedRequests: requests.failed,
    durationMs: report.run.timings.completed - report.run.timings.started
  }
};

// 1. Récupération des données extraites des nœuds précédents
// (Ajuste les noms de nœuds s'ils diffèrent dans ton workflow)
const cypressData = $("Json Cypress").first().json;
const newmanData = $("Json Newman").first().json;

// 2. Extraction des échecs Cypress (UI)
const uiFailures = cypressData.failedTests || [];
const uiHasFailures = cypressData.failed > 0 || uiFailures.length > 0;

// 3. Extraction des échecs Newman (API)
// En fonction de la structure envoyée par Json Newman (ex: assertions échouées)
const apiFailures = newmanData.failedTests || newmanData.failures || [];
const apiHasFailures = (newmanData.failed > 0) || apiFailures.length > 0;

// 4. Calcul du statut global
const hasFailures = uiHasFailures || apiHasFailures;

// 5. Structure du JSON unifié transmis au nœud suivant (IF / OpenAI)
return [{
  json: {
    hasFailures: hasFailures,
    summary: {
      totalApiFailed: newmanData.failed || apiFailures.length,
      totalUiFailed: cypressData.failed || uiFailures.length,
      executionDate: new Date().toISOString()
    },
    details: {
      apiFailures: apiFailures,
      uiFailures: uiFailures
    }
  }
}];
